(() => {
  const video=document.getElementById('recording-preview-video');
  if(!video)return;
  const title=document.getElementById('recording-preview-title');
  const counter=document.getElementById('recording-counter');
  const pause=document.getElementById('recording-pause');
  let position=0,paused=false,timer;
  function schedule(){clearTimeout(timer);if(!paused)timer=setTimeout(()=>show(position+1),10000);}
  function show(next){
    video.pause();position=(next+dldRecordings.length)%dldRecordings.length;
    const item=dldRecordings[position];
    video.removeAttribute('src');video.load();video.poster=item.poster;
    video.controls=false;video.muted=true;video.setAttribute('aria-label',item.title);
    title.textContent=item.title;counter.textContent=`${position+1} de ${dldRecordings.length}`;
    schedule();
  }
  document.getElementById('recording-prev').addEventListener('click',()=>show(position-1));
  document.getElementById('recording-next').addEventListener('click',()=>show(position+1));
  pause.addEventListener('click',()=>{paused=!paused;pause.textContent=paused?'Continuar':'Pausar';pause.setAttribute('aria-pressed',String(paused));if(paused)clearTimeout(timer);else schedule();});
  document.getElementById('recording-listen').addEventListener('click',()=>{
    clearTimeout(timer);paused=true;pause.textContent='Continuar';pause.setAttribute('aria-pressed','true');
    if(!video.getAttribute('src'))video.src=dldRecordings[position].src;
    video.controls=true;video.muted=false;video.play().catch(()=>{});
  });
  document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(timer);else if(!video.getAttribute('src'))schedule();});
  show(0);
})();
